import { sql, type SQL } from "drizzle-orm";
import { bigint, timestamp, uuid, type AnyPgColumn } from "drizzle-orm/pg-core";

/** Primary key. Values come from lib/id.ts (UUID v7) — never generated by the database. */
export const id = () => uuid("id").primaryKey();

/** Money as integer paise. bigint so large one-off fees cannot overflow. */
export const paise = (name: string) => bigint(name, { mode: "number" });

export const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
export const updatedAt = () => timestamp("updated_at", { withTimezone: true }).notNull().defaultNow();
/** Soft delete: nothing is ever hard-deleted. */
export const deletedAt = () => timestamp("deleted_at", { withTimezone: true });

export const timestamps = () => ({ createdAt: createdAt(), updatedAt: updatedAt(), deletedAt: deletedAt() });

/** SQL for a CHECK constraint that keeps a text column inside a TypeScript union. */
export function oneOf(column: AnyPgColumn, values: readonly string[]): SQL {
  return sql`${column} in (${sql.join(
    values.map((v) => sql.raw(`'${v.replace(/'/g, "''")}'`)),
    sql`, `,
  )})`;
}
